 input.oninput=updateCount;document.querySelectorAll("[data-prompt]").forEach(el=>el.onclick=()=>{input.value=el.dataset.prompt;updateCount();input.focus();});
 const previous=Math.ceil((Number(sessionStorage.getItem("fluxlake_demo_retry_until"))-Date.now())/1000);
 if(previous>0&&available)showDemoCooldown(previous,available);
 document.getElementById("agent-form").onsubmit=async e=>{
  e.preventDefault();if(!available)return;const target=document.getElementById("agent-result");button.disabled=true;button.innerHTML='<span class="spinner"></span>Investigating…';target.setAttribute("aria-busy","true");target.innerHTML='<div class="loading"><span class="spinner"></span>Reading real public evidence…</div>';
  try{const r=await api("/api/workspace/agent/demo",{method:"POST",body:JSON.stringify({question:input.value})});analystResult=r;target.innerHTML=renderInvestigation(r);}
  catch(err){target.innerHTML=err.retryAfter?`<div class="cooldown-panel" role="status"><strong>The free allowance is cooling down.</strong><p>${esc(err.message)} Try again when the countdown ends.</p></div>`:`<div class="notice error">${esc(err.message)}</div>`;if(err.retryAfter)showDemoCooldown(err.retryAfter,available);}
  finally{target.setAttribute("aria-busy","false");if(Number(sessionStorage.getItem("fluxlake_demo_retry_until"))<=Date.now()){button.disabled=!available;button.innerHTML=`Investigate public sample ${icon("arrow")}`;}}
 };
