async function access(){content.innerHTML=panel("Operator session","Use the private bearer token already configured for this workspace",`<div class="panel-body access-form"><form id="access-form"><label for="operator-token">Private operator bearer token</label><input id="operator-token" type="password" autocomplete="off" spellcheck="false" minlength="32" maxlength="4096" required placeholder="Paste your private token"><p class="integration-note">Stored in this tab’s session storage until you clear it or close the session. Sent only in an Authorization header to this origin. Never included in an export or URL.</p><div class="actions"><button class="button" type="submit">Connect and verify →</button><button class="button secondary" type="button" id="clear-token">Clear session</button></div></form><div class="access-status">${token()?badge("Token present"):badge("Public exploration","neutral")}<span id="access-result">${token()?"Verify to confirm this token is valid.":"No operator credentials are stored in this tab."}</span></div><div class="notice info">Public-source reads are open. Private payment CDC operations stay protected by the existing bearer boundary. A public GitHub token is not needed for the source connection.</div></div>`);document.getElementById("access-form").onsubmit=async e=>{e.preventDefault();const value=document.getElementById("operator-token").value.trim();try{const r=await fetch("/pipeline",{headers:{Authorization:"Bearer "+value}});if(!r.ok)throw new Error(r.status===401?"The token was rejected.":"Protected operations are unavailable.");sessionStorage.setItem("fluxlake_operator_token",value);document.getElementById("operator-token").value="";message("Operator token verified for private operations. The public analyst works without a token.");document.getElementById("access-result").textContent="Verified operator session.";}catch(err){message(err.message,true);}};document.getElementById("clear-token").onclick=()=>{sessionStorage.removeItem("fluxlake_operator_token");message("Operator token cleared from this tab.");access();upgradeIcons(content);};}
function upgradeIcons(root){
 const symbols={"↗":"external","→":"arrow","←":"arrow","↓":"download","↻":"refresh","◇":"file","⌘":"github","✧":"message","▤":"database","▥":"layers","◫":"overview","⌁":"lineage","◈":"overview","◷":"clock","⌕":"search"};
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];let node;
 while((node=walker.nextNode()))if(/[↗→←↓↻◇⌘✧▤▥◫⌁◈◷⌕]/.test(node.textContent)&&!node.parentElement.closest("svg,pre,code,textarea,input,.agent-answer"))nodes.push(node);
 for(const text of nodes){const fragment=document.createDocumentFragment();for(const piece of text.textContent.split(/([↗→←↓↻◇⌘✧▤▥◫⌁◈◷⌕])/)){if(symbols[piece]){const holder=document.createElement("span");holder.innerHTML=icon(symbols[piece]);if(piece==="←")holder.firstChild.classList.add("reverse-icon");fragment.append(holder.firstChild);}else fragment.append(document.createTextNode(piece));}text.replaceWith(fragment);}
}
