let commandIndex=0,commandRequest=0,commandTimer,commandAbort;
function chooseCommand(index){const options=[...commandResults.querySelectorAll(".command-option")];commandIndex=Math.max(0,Math.min(index,options.length-1));options.forEach((el,i)=>{el.classList.toggle("active",i===commandIndex);el.setAttribute("aria-selected",String(i===commandIndex));});if(options[commandIndex]){commandInput.setAttribute("aria-activedescendant",options[commandIndex].id);options[commandIndex].scrollIntoView({block:"nearest"});}else commandInput.removeAttribute("aria-activedescendant");}
function paintCommands(routes,events=[],pending=false,error=false){let index=0;commandResults.innerHTML=`${routes.length?'<div class="command-group">Navigate</div>':""}${routes.map(([key,label,description,symbol])=>`<a class="command-option" role="option" id="command-option-${index++}" href="/workspace/${key}">${icon(symbol)}<span><strong>${esc(label)}</strong><small>${esc(description)}</small></span>${icon("arrow")}</a>`).join("")}${events.length?'<div class="command-group">Retained source events</div>':""}${events.map(row=>`<a class="command-option" role="option" id="command-option-${index++}" href="/workspace/silver?q=${encodeURIComponent(row.event_id)}" data-open-event="${esc(row.event_id)}">${icon("file")}<span><strong>${esc(row.repository)}</strong><small>${esc(row.event_type)} · ${esc(row.event_id)} · ${esc(row.actor)}</small></span>${icon("chevron")}</a>`).join("")}${pending?'<div class="command-empty">Searching actual retained records…</div>':error?'<div class="command-empty">Source search is temporarily unavailable.</div>':!routes.length&&!events.length?'<div class="command-empty">No matching pages or retained events.</div>':""}`;chooseCommand(0);}
async function searchCommands(){const query=commandInput.value.trim(),ticket=++commandRequest;commandAbort?.abort();const routes=NAV.filter(row=>row.slice(0,3).join(" ").toLowerCase().includes(query.toLowerCase()));paintCommands(routes,[],query.length>=2);if(query.length<2)return;commandAbort=new AbortController();try{const data=await api(`/api/workspace/silver?${new URLSearchParams({q:query,limit:"5"})}`,{signal:commandAbort.signal});if(ticket===commandRequest&&palette.open)paintCommands(routes,data.rows);}catch(err){if(err.name!=="AbortError"&&ticket===commandRequest&&palette.open)paintCommands(routes,[],false,true);}}
function openCommand(){closeNavigation();if(detail.open)detail.close();if(!palette.open)palette.showModal();commandInput.value="";paintCommands(NAV);commandInput.focus();}
document.getElementById("command-trigger").onclick=openCommand;document.getElementById("close-command").onclick=()=>palette.close();
commandInput.oninput=()=>{clearTimeout(commandTimer);commandTimer=setTimeout(searchCommands,180);};
commandInput.onkeydown=e=>{if(e.key==="ArrowDown"||e.key==="ArrowUp"){e.preventDefault();const options=commandResults.querySelectorAll(".command-option");chooseCommand((commandIndex+(e.key==="ArrowDown"?1:-1)+options.length)%Math.max(1,options.length));}else if(e.key==="Enter"){e.preventDefault();commandResults.querySelectorAll(".command-option")[commandIndex]?.click();}};
commandResults.onclick=e=>{const event=e.target.closest("[data-open-event]");if(event){e.preventDefault();palette.close();inspectEvent(event.dataset.openEvent);}};
palette.addEventListener("close",()=>{commandRequest++;clearTimeout(commandTimer);commandAbort?.abort();});
document.addEventListener("keydown",e=>{const typing=e.target.matches("input,textarea,select")||e.target.isContentEditable;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"||e.key==="/"&&!typing){e.preventDefault();openCommand();}if(e.key==="Escape")closeNavigation(true);if(e.key==="Tab"&&document.body.classList.contains("nav-open")){const items=[...document.querySelectorAll(".sidebar a,.sidebar button")],first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
const loaders={overview,sources,ingestion,bronze:explorer,silver:explorer,gold,schema,drift,replay,quarantine,runs,lineage,agent,access};
async function load(){if(loading)return;loading=true;content.setAttribute("aria-busy","true");const refresh=document.getElementById("refresh");refresh.disabled=true;try{await loaders[page]();upgradeIcons(content);document.querySelectorAll("[data-width]").forEach(el=>el.style.width=`${Math.max(0,Math.min(100,Number(el.dataset.width)))}%`);}catch(err){content.innerHTML=`<section class="panel">${empty("The event store is unavailable",esc(err.message))}<div class="panel-body"><p class="small muted">Refresh after the source store is available. No substitute totals are displayed.</p></div></section>`;}finally{loading=false;content.setAttribute("aria-busy","false");refresh.disabled=false;}}
document.getElementById("refresh").onclick=()=>{notice.innerHTML="";load();};
const initial=new URLSearchParams(location.search);state.q=(initial.get("q")||"").slice(0,100);state.type=(initial.get("event_type")||"").slice(0,80);
load();
